export type collectionsControllerCompleteCollectionResponse200 = {
  data: void;
  status: 200;
};

export type collectionsControllerCompleteCollectionResponseSuccess =
  collectionsControllerCompleteCollectionResponse200 & {
    headers: Headers;
  };
export type collectionsControllerCompleteCollectionResponse =
  collectionsControllerCompleteCollectionResponseSuccess;

export const getCollectionsControllerCompleteCollectionUrl = (id: string) => {
  return `/collections/${id}/complete`;
};

/**
 * @summary Clôturer la collecte et générer automatiquement l'expédition et ses colis
 */
export const collectionsControllerCompleteCollection = async (
  id: string,
  completeCollectionDto: CompleteCollectionDto,
  options?: Parameters<typeof customFetch>[1],
): Promise<collectionsControllerCompleteCollectionResponse> => {
  const getHeaders = (
    h?: NonNullable<RequestInit["headers"]>,
  ): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
  return customFetch<collectionsControllerCompleteCollectionResponse>(
    getCollectionsControllerCompleteCollectionUrl(id),
    {
      ...options,
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        ...getHeaders(options?.headers),
      },
      body: JSON.stringify(completeCollectionDto),
    },
  );
};

export const getCollectionsControllerCompleteCollectionQueryKey = (
  id: string,
  completeCollectionDto?: CompleteCollectionDto,
) => {
  return [
    "POST",
    `/collections/${id}/complete`,
    completeCollectionDto,
  ] as const;
};

export const getCollectionsControllerCompleteCollectionQueryOptions = <
  TData = Awaited<ReturnType<typeof collectionsControllerCompleteCollection>>,
  TError = unknown,
>(
  id: string,
  completeCollectionDto: CompleteCollectionDto,
  options?: {
    query?: Partial<
      UseQueryOptions<
        Awaited<ReturnType<typeof collectionsControllerCompleteCollection>>,
        TError,
        TData
      >
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ??
    getCollectionsControllerCompleteCollectionQueryKey(
      id,
      completeCollectionDto,
    );

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof collectionsControllerCompleteCollection>>
  > = ({ signal }) =>
    collectionsControllerCompleteCollection(id, completeCollectionDto, {
      signal,
      ...requestOptions,
    });

  return {
    queryKey,
    queryFn,
    enabled: id !== null && id !== undefined,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof collectionsControllerCompleteCollection>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

